window.ScripturaLexicons.BDAG_PART_0152 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euthytes-bdag\" data-source=\"BDAG\" data-search=\"εὐθύτης, ητος, ἡ euthýtēs substantivo feminino retidão; justiça; integridade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐθύτης, ητος, ἡ</td><td>substantivo feminino</td><td>retidão; justiça; integridade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eukaireo-bdag\" data-source=\"BDAG\" data-search=\"εὐκαιρέω eukairéō verbo dispor de tempo; ter oportunidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐκαιρέω</td><td>verbo</td><td>dispor de tempo; ter oportunidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eukairia-bdag\" data-source=\"BDAG\" data-search=\"εὐκαιρία, ας, ἡ eukairía substantivo feminino oportunidade favorável; momento propício BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐκαιρία, ας, ἡ</td><td>substantivo feminino</td><td>oportunidade favorável; momento propício</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eukairos-bdag\" data-source=\"BDAG\" data-search=\"εὔκαιρος, ον eúkairos adjetivo oportuno; apropriado; que vem na hora certa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὔκαιρος, ον</td><td>adjetivo</td><td>oportuno; apropriado; que vem na hora certa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eukairos-adv-bdag\" data-source=\"BDAG\" data-search=\"εὐκαίρως eukaírōs advérbio oportunamente; no momento conveniente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐκαίρως</td><td>advérbio</td><td>oportunamente; no momento conveniente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eukatallaktos-bdag\" data-source=\"BDAG\" data-search=\"εὐκατάλλακτος, ον eukatállaktos adjetivo facilmente aplacável; favorável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐκατάλλακτος, ον</td><td>adjetivo</td><td>facilmente aplacável; favorável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euklees-bdag\" data-source=\"BDAG\" data-search=\"εὐκλεής, ές, eukleḗs adjetivo célebre; renomado; de boa reputação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐκλεής, ές,</td><td>adjetivo</td><td>célebre; renomado; de boa reputação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eukleos-bdag\" data-source=\"BDAG\" data-search=\"εὐκλεῶς eukleṓs advérbio gloriosamente; de modo honroso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐκλεῶς</td><td>advérbio</td><td>gloriosamente; de modo honroso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eukolos-bdag\" data-source=\"BDAG\" data-search=\"εὐκόλως eukólōs advérbio facilmente; sem dificuldade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐκόλως</td><td>advérbio</td><td>facilmente; sem dificuldade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eukopos-bdag\" data-source=\"BDAG\" data-search=\"εὔκοπος, ον eúkopos adjetivo fácil; mais fácil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὔκοπος, ον</td><td>adjetivo</td><td>fácil; mais fácil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eukopos-adv-bdag\" data-source=\"BDAG\" data-search=\"εὐκόπως eukópōs advérbio facilmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐκόπως</td><td>advérbio</td><td>facilmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euktaios-bdag\" data-source=\"BDAG\" data-search=\"εὐκταῖος, α, ον euktaíōs adjetivo desejado; objeto de súplica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐκταῖος, α, ον</td><td>adjetivo</td><td>desejado; objeto de súplica</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eulabeia-bdag\" data-source=\"BDAG\" data-search=\"εὐλάβεια, ας, ἡ eulábeia substantivo feminino reverência; temor de Deus; cautela; ansiedade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐλάβεια, ας, ἡ</td><td>substantivo feminino</td><td>reverência; temor de Deus; cautela; ansiedade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eulabeomai-bdag\" data-source=\"BDAG\" data-search=\"εὐλαβέομαι eulabéomai verbo depoente passivo preocupar-se; acautelar-se; reverenciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐλαβέομαι</td><td>verbo depoente passivo</td><td>preocupar-se; acautelar-se; reverenciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eulabes-bdag\" data-source=\"BDAG\" data-search=\"εὐλαβής, ές, eulabḗs adjetivo devoto; temente a Deus; reverente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐλαβής, ές,</td><td>adjetivo</td><td>devoto; temente a Deus; reverente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eulalos-bdag\" data-source=\"BDAG\" data-search=\"εὔλαλος, ον eúlalos adjetivo loquaz; palavroso; de fala insinuante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὔλαλος, ον</td><td>adjetivo</td><td>loquaz; palavroso; de fala insinuante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eulogeo-bdag\" data-source=\"BDAG\" data-search=\"εὐλογέω eulogéō verbo louvar; bendizer; abençoar; conceder benefícios BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐλογέω</td><td>verbo</td><td>louvar; bendizer; abençoar; conceder benefícios</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eulogetos-bdag\" data-source=\"BDAG\" data-search=\"εὐλογητός, ή, όν eulogētós adjetivo bendito; louvado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐλογητός, ή, όν</td><td>adjetivo</td><td>bendito; louvado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eulogia-bdag\" data-source=\"BDAG\" data-search=\"εὐλογία, ας, ἡ eulogía substantivo feminino louvor; lisonja; bênção; dádiva generosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐλογία, ας, ἡ</td><td>substantivo feminino</td><td>louvor; lisonja; bênção; dádiva generosa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eulogos-bdag\" data-source=\"BDAG\" data-search=\"εὔλογος, ον eúlogos adjetivo razoável; correto; sensato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὔλογος, ον</td><td>adjetivo</td><td>razoável; correto; sensato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-euthytes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐθύτης, ητος, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euthýtēs⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐθύτης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span>. Originalmente, «retidão; caráter reto» (Aristóteles e outros). Na literatura aqui abrangida, somente em sentido <strong>figurado: retidão; justiça; integridade</strong> (LXX; PsSol 2:15; TestIss 3:1; TestGad 7:7; ApcMos 27; Syntipas 125, 8; Pselo, p. 238, 1, com <span class=\"greek\">δικαιοσύνη</span> e <span class=\"greek\">φιλανθρωπία</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">ῥάβδος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐθύτητος</span>, «o cetro justo» (genitivo de qualidade), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:8</a> (Sl 44:7); 1Cl 14:5 (Sl 36:37). <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, «andar na retidão do Senhor», Hv 3, 5, 3. Bibliografia: DELG, s.v. <span class=\"greek\">εὐθύς</span>.</p></section></article>\n<article id=\"entry-eukaireo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκαιρέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eukairéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐκαιρέω</span>. Imperfeito <span class=\"greek\">εὐκαίρουν</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:31</a> e <span class=\"greek\">ηὐκαίρουν</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:21</a> (ver W-S §12, 5b; B-D-F §67, 1); primeiro aoristo do subjuntivo <span class=\"greek\">εὐκαιρήσω</span>. Ver os dois verbetes seguintes e <span class=\"greek\">καιρός</span>. Políbio e outros; inscrições e papiros. <strong>Experimentar momento ou ocasião favorável para uma atividade; ter tempo, lazer ou oportunidade.</strong> Frínico 125, Lob., censura o emprego do verbo (<span class=\"greek\">οὐ</span> <span class=\"greek\">λεκτέον</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">εὖ</span> <span class=\"greek\">σχολῆς</span> <span class=\"greek\">ἔχειν</span>: «não se deve dizê-lo; mas, sim, empregar a expressão ‹ter tempo livre›»).</p><p class=\"entry-text\"><strong>Uso absoluto</strong> (Políbio 20, 9, 4; papiros): <span class=\"greek\">ἐλεύσεται</span> <span class=\"greek\">ὅταν</span> <span class=\"greek\">εὐκαιρήσῃ</span>, «virá assim que encontrar oportunidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16:12</a>; cf. PEleph 29, 7 [séc. III a.C.] <span class=\"greek\">ἐὰν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εὐκαιρῇς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διαβῆναι</span> e UPZ 71, 18 [152 a.C.].</p><p class=\"entry-text\"><strong>Seguido de infinitivo</strong> (Plutarco, Mor. 223; Ps.-Luciano, Amor. 33): <span class=\"greek\">φαγεῖν</span>, «ter tempo para comer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:31</a>; cf. PSI 425, 29 [séc. III a.C.] <span class=\"greek\">εἰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εὐκαιρεῖ</span> <span class=\"greek\">τις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">παρά</span> <span class=\"greek\">σοι</span> <span class=\"greek\">γραμματέων</span>, <span class=\"greek\">ἀπόστειλόν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">κτλ</span>.</p><p class=\"entry-text\"><strong>Com <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> e infinitivo:</strong> <span class=\"greek\">εἰς</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἕτερον</span> <span class=\"greek\">ηὐκαίρουν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">λέγειν</span>, «costumavam ocupar o tempo com nenhuma outra coisa além de falar», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:21</a>. Bibliografia: DELG, s.v. <span class=\"greek\">καιρός</span>; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-eukairia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκαιρία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eukairía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐκαιρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver o verbete precedente e os dois seguintes. <strong>Oportunidade favorável; momento oportuno</strong>; uso desde Platão, Phdr. 272a; também BGU 665 II, 4 [séc. I d.C.] e outros; TestJos 7:3; cf. Sl 144:15; 1Mc 11:42. <span class=\"greek\">ζητεῖν</span> <span class=\"greek\">εὐκαιρίαν</span>, «procurar uma ocasião propícia» (Josefo, Ant. 20, 76), seguido de <span class=\"greek\">ἵνα</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:16</a>. <strong>Seguido do genitivo do infinitivo com artigo</strong>, cf. BGU 46, 18 [193 d.C.] <span class=\"greek\">ἐὰν</span> <span class=\"greek\">εὐκαιρίας</span> <span class=\"greek\">τύχω</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὑρεῖν</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:6</a>. Ver B-D-F §400, 1; Mlt. 216–18; Mlt-H. 448–50. Bibliografia: M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-eukairos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκαιρος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eúkairos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὔκαιρος</span>, <span class=\"greek\">ον</span>. Ver os dois verbetes precedentes. Sófocles, Hipócrates e posteriores; Esopo, Fab. 248b H. // 141, variante P. // 146 H-H. Na literatura aqui abrangida, somente <strong>referente a um tempo considerado ocasião favorável: oportuno; apropriado; que ocorre no momento certo.</strong> <span class=\"greek\">ἡμέρα</span>, «dia propício», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:21</a> (Herodiano 1, 9, 6, <span class=\"greek\">καιρὸς</span> <span class=\"greek\">εὔκαιρος</span>; 2Mc 14:29; J. Greig, ET 65 [1953/54], 158s.). <strong>Que vem no momento necessário</strong> (Plutarco, Mor. 10e, <span class=\"greek\">εὔκαιρος</span> <span class=\"greek\">σιγή</span>, «silêncio oportuno»; Sl 103:27): <span class=\"greek\">βοήθεια</span>, «socorro no momento de necessidade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:16</a> (OGI 762, 4 <span class=\"greek\">βοηθείτω</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εὔκαιρον</span>; cf. Cat. Cod. Astr. XII 168, 2). Bibliografia: M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-eukairos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκαίρως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eukaírōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐκαίρως</span>, advérbio. Ver os três verbetes precedentes. Desde Xenofonte, Ages. 8, 3; SIG 495, 43; PHal 17, 6 [séc. III a.C.]; PLond I, 33, 23, p. 20 [161 a.C.]; Sir 18:22; Fílon, Somn. 2, 252; Josefo, Ant. 14, 323. <strong>Convenientemente; em ocasião propícia:</strong> <span class=\"greek\">παραδιδόναι</span>, «entregar em ocasião conveniente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:11</a>. <span class=\"greek\">εὐ</span>. <span class=\"greek\">ἀκαίρως</span>, «a tempo e fora de tempo», isto é, «quando for conveniente e quando não for conveniente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 4:2</a> (sobre o assíndeto, ver Kühner-G. II 346d; exemplos retóricos em A. Malherbe, JBL 103 [1984], 235–43; <em>Reader, Polemo</em>, p. 361; ver <span class=\"greek\">ἀκαίρως</span>). <span class=\"greek\">εὐκαίρως</span> <span class=\"greek\">ἔχειν</span>, «dispor de tempo livre» (Políbio 5, 26, 10; papiros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:31</a>, códice D. Bibliografia: M-M; Spicq.</p></section></article>\n<article id=\"entry-eukatallaktos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκατάλλακτος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eukatállaktos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐκατάλλακτος</span>, <span class=\"greek\">ον</span>. Aristóteles, Rhet. 2, 4, 1831b 5, conforme a referência impressa. <strong>Facilmente aplacável; favorável</strong>, referido a Deus (3Mc 5:13): Hv 1, 1, 8. Bibliografia: DELG, s.v. <span class=\"greek\">ἄλλος</span>; Frisk, s.v. <span class=\"greek\">ἀλλάσσω</span>.</p></section></article>\n<article id=\"entry-euklees-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκλεής, ές,</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eukleḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐκλεής</span>, <span class=\"greek\">ές</span>, genitivo <span class=\"greek\">οῦς</span>. Ver o verbete seguinte. Homero e posteriores; Wsd 3:15; Jr 31:17; Fílon; Josefo, Bell. 4, 250; Ant. 19, 240. <strong>Que é objeto de elogios públicos; célebre; afamado; renomado.</strong> Em associação com <span class=\"greek\">σεμνός</span>: <span class=\"greek\">κανὼν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παραδόσεως</span>, «regra renomada que nos foi transmitida pela tradição», 1Cl 7:2. Bibliografia: DELG, s.v. <span class=\"greek\">κλέος</span>.</p></section></article>\n<article id=\"entry-eukleos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκλεῶς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eukleṓs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐκλεῶς</span>, advérbio. Ver o verbete precedente. Ésquilo e outros. <strong>De maneira que suscita elogios públicos; gloriosamente; honrosamente.</strong> Com <span class=\"greek\">φέρειν</span>, a respeito daqueles que padeceram de tal modo que alcançaram renome: 1Cl 45:5.</p></section></article>\n<article id=\"entry-eukolos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκόλως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eukólōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐκόλως</span>, advérbio, em oposição a <span class=\"greek\">δυσκόλως</span>. Desde Xenofonte, Mem. 4, 8, 2; Herm. Wr. 13, 16; PCairMasp 2 III, 23; 4, 19. <strong>Com facilidade, sem impor encargos; facilmente</strong>: Hm 12, 3, 5, variante textual no lugar de <span class=\"greek\">εὐκόπως</span>. Bibliografia: DELG, s.v. <span class=\"greek\">κόλον</span>.</p></section></article>\n<article id=\"entry-eukopos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔκοπος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eúkopos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὔκοπος</span>, <span class=\"greek\">ον</span>. Ver <span class=\"greek\">κόπος</span> e o verbete seguinte. Políbio 18, 18, 2; LXX. <strong>Fácil.</strong> Na literatura aqui abrangida, somente no comparativo <strong><span class=\"greek\">εὐκοπώτερος</span></strong>, «mais fácil» (Dioscórides I 39 W.): Hm 12, 4, 5. No NT, sempre na expressão <span class=\"greek\">εὐκοπώτερόν</span> <span class=\"greek\">ἐστιν</span>, «é mais fácil», seguida de infinitivo (cf. Sir 22:15): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:23</a>. Com acusativo seguido de infinitivo (cf. 1Mc 3:18): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:17</a>; 18:25. Bibliografia: DELG, s.v. <span class=\"greek\">κόπτω</span>; M-M.</p></section></article>\n<article id=\"entry-eukopos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκόπως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eukópōs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐκόπως</span>, advérbio. Ver o verbete precedente. Hipócrates, Aristófanes, Diodoro Sículo; Plutarco, Mor. 726e; POxy 1467, 14; EpArist 208; 250. <strong>Facilmente</strong>: <span class=\"greek\">φυλάσσειν</span>, «guardar facilmente», Hm 12, 3, 5.</p></section></article>\n<article id=\"entry-euktaios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐκταῖος, α, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euktaíōs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐκταῖος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span>. <strong>Que é objeto de petição; aquilo por que se ora; desejado</strong>. Assim Ésquilo, Platão e posteriores; PGiss 68, 3 [séc. II d.C.]; Fílon; Josefo, Ant. 1, 292 e outros; Melitão, HE 4, 26, 7. <span class=\"greek\">εἰρήνη</span>, «paz desejada», 1Cl 65:1, junto de <span class=\"greek\">ἐπιπόθητος</span>. Bibliografia: DELG, s.v. <span class=\"greek\">εὔχομαι</span>.</p></section></article>\n<article id=\"entry-eulabeia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλάβεια, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eulábeia⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐλάβεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver os dois verbetes seguintes; forma <span class=\"greek\">εὐλαβίη</span> em Teógnis 1, 118; trágicos, Platão e outros; OGI 315, 69; UPZ 42, 22 [162 a.C.]; LXX; Fílon; Josefo.</p><p class=\"entry-text\">O sentido primário refere-se ao <strong>exercício de cautela</strong>. Na relação com a esfera transcendente, é especialmente necessário evitar ofender as divindades; daí «reverência; piedade». Na literatura aqui abrangida, provavelmente somente <strong>reverente temor diante da presença de Deus; reverência; temor de Deus</strong> (Diodoro Sículo 13, 12, 7, <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">εὐ</span>.; Plutarco, Camill. 139 [21, 2]; Numa 75 [22, 7]; Aemil. Paul. 256 [3, 2]; Mor. 549e, 568c [«hesitação»]; UPZ, citado acima; Pv 28:14; Fílon, Cherub. 29, <span class=\"greek\">εὐ</span>. <span class=\"greek\">θεοῦ</span>; Rer. Div. Her. 22; 29). <span class=\"greek\">μετὰ</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">δέους</span>, «com temor reverente e respeito», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:28</a> (ver <span class=\"greek\">δέος</span>; cf. Epicarmo 221 Kaibel). <span class=\"greek\">μετὰ</span> <span class=\"greek\">φόβου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">εὐ</span>., «com temor e toda reverência», Pol 6:3.</p><p class=\"entry-text\">Provavelmente também <span class=\"greek\">εἰσακουσθεὶς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐ</span>., «ouvido por causa de sua piedade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:7</a> (ver <span class=\"greek\">ἀπό</span> 5a; J. Jeremias, ZNW 43 [1952/53], 107–11; A. Strobel, ZNW 45 [1954], 252–66).</p><p class=\"entry-text\"><strong>Interpretação alternativa em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:7</a>:</strong> outros intérpretes, como Harnack, SBBerlAk (1929), 69–73 = <em>Studien</em> I, 245–52, e H. Strathmann, 4.ª ed. (1947), ad loc., preferem entender a palavra como «medo; ansiedade» (conforme Demóstenes 23, 15; Plutarco, Fab. 174 [1, 2]; Herodiano 5, 2, 2; Wsd 17:8; Fílon, Leg. All. 3, 113; Virt. 24; Josefo, Ant. 11, 239; 12, 255), resultando em «ouvido [e livrado] de sua ansiedade». O substantivo <span class=\"greek\">εὐ</span>. possui ainda o sentido de <strong>escrúpulo; hesitação</strong> em Plutarco, Mor. 568c. Bibliografia: DELG, s.v. <span class=\"greek\">λαμβάνω</span>; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-eulabeomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλαβέομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eulabéomai⟧</span><span class=\"separator\">·</span><span>verbo depoente passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐλαβέομαι</span>. <strong>Verbo depoente de forma passiva.</strong> Imperfeito, terceira pessoa do singular <span class=\"greek\">εὐλαβεῖτο</span> (LXX); segunda pessoa do plural <span class=\"greek\">ηὐλαβεῖσθε</span> (Justino, D. 123, 3); primeiro futuro <span class=\"greek\">εὐλαβηθήσομαι</span> (LXX); primeiro aoristo <span class=\"greek\">εὐλαβήθην</span> (LXX); particípio <span class=\"greek\">εὐλαβηθείς</span>. Ver o verbete precedente. Trágicos, Platão e posteriores; inscrições; papiros; LXX; En; Fílon; Josefo; Justino, D. 7, 1; 123, 3.</p><p class=\"entry-text\">① <strong>Estar preocupado com algum assunto: preocupar-se; sentir ansiedade; recear</strong> (Sófocles, Oed. R. 47 e outros; Políbio 18, 23, 5; Diodoro Sículo 4, 73, 2; 16, 22, 2; UPZ 119, 5 [156 a.C.]; LXX; Josefo, Ant. 1, 283). Seguido de <span class=\"greek\">μή</span>, «para que não; receando que» (Políbio 3, 111; Diodoro Sículo 2, 13, 4; Epicteto 4, 13, 4; 1Mc 12:40; En 106:6; Josefo, Ant. 6, 157; 8, 333): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:10</a>, variante textual; 1Cl 44:5.</p><p class=\"entry-text\">Talvez também <span class=\"greek\">Νῶε</span> … <span class=\"greek\">εὐλαβηθεὶς</span> <span class=\"greek\">κατεσκεύασεν</span> <span class=\"greek\">κιβωτόν</span>, «Noé … ficou apreensivo e construiu uma arca», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:7</a>; alternativamente, «Noé tomou precauções» (cf. Platão, Gorg. 519a <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εὐλαβῇ</span>; Sb 4650, 13 <span class=\"greek\">εὐλαβήθητι</span> <span class=\"greek\">μήπως</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">καταλάβουσίν</span> <span class=\"greek\">σε</span>; Sir 18:27; EpJer 4). Muitos, porém, preferem o sentido seguinte.</p><p class=\"entry-text\">② <strong>Demonstrar consideração reverente: reverenciar; respeitar</strong> (Platão, Leg. 9, p. 879e <span class=\"greek\">τ</span>. <span class=\"greek\">ξενικὸν</span> <span class=\"greek\">θεόν</span>; Pv 2:8; 30:5; Na 1:7 e outros; Fílon, Rer. Div. Her. 29; Josefo, Ant. 6, 259, <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span>). <span class=\"greek\">εὐλαβηθείς</span> (subentendido <span class=\"greek\">θεόν</span>), «movido por reverência [a Deus]», isto é, à sua ordem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:7</a>. Bibliografia: K. Kerényi, «<span class=\"greek\">Εὐλάβεια</span>», <em>Byz.-Neugr. Jahrb.</em> 8 (1930), 306–16; W. Schmid, PhilolWoch 51 (1931), 708s.; J. van Herten, <em><span class=\"greek\">Θρησκεία</span>, <span class=\"greek\">Εὐλάβεια</span>, <span class=\"greek\">Ἱκέτης</span></em>, tese, Utrecht (1934); M-M; TW.</p></section></article>\n<article id=\"entry-eulabes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλαβής, ές,</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eulabḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐλαβής</span>, <span class=\"greek\">ές</span>, genitivo <span class=\"greek\">οῦς</span>; comparativo <span class=\"greek\">εὐλαβέστερος</span>. Ver os dois verbetes precedentes. Platão e outros; inscrições, papiros, LXX, Fílon; Josefo, Ant. 2, 217; 6, 179 e outros; Justino, D. 79, 2, <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">τοῦτο</span>; advérbio comparativo em Eurípides, Iph. T. 1375. Na literatura aqui abrangida, somente <strong>referente a atitudes religiosas: devoto; temente a Deus</strong> (cf. Demóstenes 21, 61, <span class=\"greek\">εὐλαβῶς</span> com <span class=\"greek\">εὐσεβῶς</span>; Mq 7:2, onde ambas as palavras ocorrem no texto e como variantes). <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span>, «segundo a norma da Lei», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 22:12</a>; junto de <span class=\"greek\">δίκαιος</span>, como Platão, Pol. 311b, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:25</a>. <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">εὐ</span>., «homens devotos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:5</a>; 8:2. <span class=\"greek\">εὐλαβέστερος</span>, em sentido enfático, «suficientemente reverente», MPol 2:1. Bibliografia: M-M; TW.</p></section></article>\n<article id=\"entry-eulalos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔλαλος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eúlalos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὔλαλος</span>, <span class=\"greek\">ον</span>. Ver <span class=\"greek\">λαλέω</span>. Em sentido positivo, «de fala agradável», Anth. Pal. 5, 148, 1 [Meleagro, séc. I a.C.]; 9, 525, 6; 570, 2; Orph., Argon. 244; Achmes 39, 27; LXX. <strong>Referente a um modo de falar que produz impressão superficial favorável: falador; loquaz; de fala insinuante</strong> (Cat. Cod. Astr. XI/2, p. 125, 5). Substantivado: <span class=\"greek\">ὁ</span> <span class=\"greek\">εὔ</span>., «a pessoa de fala insinuante», 1Cl 30:4 (Jó 11:2). Bibliografia: DELG, s.v. <span class=\"greek\">λαλέω</span>.</p></section></article>\n<article id=\"entry-eulogeo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλογέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eulogéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐλογέω</span>. Imperfeito <span class=\"greek\">ηὐλόγουν</span> e <span class=\"greek\">εὐλόγουν</span> (W-S §12, 5b; Robertson 367); futuro <span class=\"greek\">εὐλογήσω</span>; primeiro aoristo <span class=\"greek\">εὐλόγησα</span> (também <span class=\"greek\">ηὐ</span>- na LXX); perfeito <span class=\"greek\">εὐλόγηκα</span>. <strong>Voz passiva:</strong> primeiro futuro passivo <span class=\"greek\">εὐλογηθήσομαι</span>; particípio perfeito <span class=\"greek\">εὐλογημένος</span> (também <span class=\"greek\">ηὐ</span>- em Is 61:9). Ver o verbete seguinte. Trágicos e posteriores; Ps.-Platão, Min. 320e; Isócrates, Archid. 43; Ps.-Aristóteles, Rhet. ad Alex. 4, 1426a, 3ss.; Políbio 1, 14, 4; Cássio Dião 42, 28; Herm. Wr.; inscrições; PSI 405, 5 [séc. III a.C.]; LXX, pseudepígrafos; Fílon; Josefo; Justino; Atenágoras 11, 2; papiros cristãos.</p><p class=\"entry-text\">① <strong>Dizer algo elogioso: falar bem de alguém; louvar; exaltar.</strong> Assim predominantemente fora da literatura aqui abrangida; cf. inscrição Pfuhl-Möbius II, 1606, 2 [séc. II d.C.], com o sentido «falar bem de alguém».</p><p class=\"entry-text\"><strong>Com <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span></strong>, «a Deus» (cf. CIG 4705b, 2 <span class=\"greek\">εὐλογῶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, referente a Pã; 4706c, 2 <span class=\"greek\">τὴν</span> <span class=\"greek\">Εἶσιν</span>, acerca de Ísis. Na tradição israelita, <span class=\"greek\">εὐ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, OGI 73, 1 [séc. III a.C.]; PGM 4, 3050s.; LXX; En 106:11; PsSol 2:33; TestSol 7:1 e outros; Josefo, Ant. 7, 380; SibOr 4, 25; Justino, A I, 67, 2): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.64\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:64</a>; 2:28; 24:53 (variante textual <span class=\"greek\">αἰνοῦντες</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:9</a>; MPol 14:2s.</p><p class=\"entry-text\"><strong>Com Cristo como objeto:</strong> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἰχθύες</span> … <span class=\"greek\">σε</span> <span class=\"greek\">εὐλογοῦσιν</span>, «os peixes te louvam», GJs 3:3; <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> … <span class=\"greek\">σε</span> <span class=\"greek\">εὐλογει</span>, «a terra te louva», MPol 19:2; cf. <em>per me dominum benedic</em>, Papias (1:3). <span class=\"greek\">τὴν</span> <span class=\"greek\">σὴν</span> <span class=\"greek\">οἰκονομίαν</span>, «a tua administração», AcPl Ha 3, 22.</p><p class=\"entry-text\"><strong>Uso absoluto: dar graças e louvar</strong> (TestAbr A 5, p. 82, 8 [Stone p. 12]): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:19</a>; 26:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:41</a>; 14:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:16</a> (ao lado de <span class=\"greek\">εὐχαριστέω</span>, como em Herm. Wr. 1, 27; ver também a inscrição confessional em F. Steinleitner, <em>D. Beicht</em> [1913], 112). <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτούς</span>, «sobre eles», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:16</a>, códice D.</p><p class=\"entry-text\">② <strong>Pedir que se conceda favor especial, especialmente invocando o poder gracioso de Deus: abençoar</strong> (LXX).</p><p class=\"entry-text\">ⓐ <strong>Sobre pessoas</strong>, com acusativo <span class=\"greek\">τινά</span>, «abençoar alguém»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:16</a>, variante textual, em lugar de <span class=\"greek\">κατευλογέω</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:50</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:1</a>, 6s. (cf. Gn 14:19; Demétrio, 722 Fgm. 1, 1 e 19; GJs 12:2, duas vezes). Opõe-se a <span class=\"greek\">καταρᾶσθαι</span>, «amaldiçoar» (Gn 12:3; EpJer 65; Fílon, Fuga 73; Mos. 2, 196; Josefo, Bell. 6, 307): 1Cl 15:3 (Sl 61:5). <span class=\"greek\">εὐ</span>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">καταρωμένους</span>, «abençoar os que amaldiçoam», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:28</a>; D 1:3. <span class=\"greek\">τοὺς</span> <span class=\"greek\">διώκοντας</span> <span class=\"greek\">ὑμᾶς</span>, «os que vos perseguem», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12:14</a>a. Bênçãos paternas proferidas por Isaque (Gn 27) e Jacó (Gn 48), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:20</a>s.; B 13:4s. Bênção sacerdotal, GJs 7:2; 12:1 (sobre 6:2, ver ③).</p><p class=\"entry-text\"><strong>Uso absoluto</strong> (Fílon, Migr. Abr. 113, em oposição a <span class=\"greek\">καταρᾶσθαι</span>): <span class=\"greek\">λοιδορούμενοι</span> <span class=\"greek\">εὐλογοῦμεν</span>, «quando somos injuriados, abençoamos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:12</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12:14</a>b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:9</a> (sobre o trato bondoso dispensado a pessoas hostis, cf. Plutarco, Mor. 88–89); Dg 5:15.</p><p class=\"entry-text\"><strong>Palavra de bênção na saudação</strong>, ao desejar o bem a alguém (4Km 4:29; 1Cr 16:43): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:34</a>. Também a aclamação <span class=\"greek\">εὐλογημένος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐρχόμενος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">κυρίου</span>, «bendito aquele que vem em nome do Senhor» (Sl 117:26): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:9</a>; 23:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:13</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 19:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:10</a>.</p><p class=\"entry-text\">ⓑ <strong>Sobre coisas, que por isso são consagradas</strong>, com acusativo <span class=\"greek\">τὶ</span>, <strong>abençoar; consagrar</strong> (Êx 23:25; 1Km 9:13; cf. Josefo, Bell. 5, 401): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:16</a>. Na linguagem da Eucaristia, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:16</a>. Provavelmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:22</a> também pertencem a esta acepção; nesse caso, o objeto é suprido pelo contexto; igualmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:41</a> (ver ① acima).</p><p class=\"entry-text\">③ <strong>Conceder favor; prover benefícios</strong>, com Deus ou Cristo como sujeito (Eurípides, Suppl. 927; PGM 4, 3050a; LXX; En 1:8; TestAbr A 1, p. 77, 15 [Stone p. 2] e outros; Justino, D. 123, 6). Com acusativo <span class=\"greek\">τινά</span>, «alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:26</a>; 1Cl 10:3 (Gn 12:2); 33:6 (Gn 1:28); <span class=\"greek\">ἐκκλησίαν</span>, «a igreja», Hv 1, 3, 4. <span class=\"greek\">εὐλογῶν</span> <span class=\"greek\">εὐλογήσω</span> <span class=\"greek\">σε</span>, «certamente te abençoarei», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:14</a> (Gn 22:17).</p><p class=\"entry-text\"><strong>Com Deus como sujeito subentendido:</strong> GJs 6:2; <span class=\"greek\">εὐλόγησον</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἐσχάτην</span> <span class=\"greek\">εὐλογίαν</span>, «abençoa-a [à menina Maria] com a bênção última ou mais excelente», ibid. Com <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, «abençoar alguém com alguma coisa» (Sl 28:11; TestJos 18:1, variante), <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">εὐλογίᾳ</span>, «com toda bênção», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:3</a> (cf. TestIss 5:6 <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐλογίαις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>; sobre a forma, cf. BGU <span class=\"greek\">βεβαιώσει</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">βεβαιώσει</span>).</p><p class=\"entry-text\"><strong>Voz passiva:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:9</a>; 1Cl 31:2; GJs 15:4 (Justino). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σπέρματί</span> <span class=\"greek\">σου</span> <span class=\"greek\">εὐλογηθήσονται</span>, «na tua descendência serão abençoados», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:25</a>, variante textual (Gn 12:3).</p><p class=\"entry-text\"><strong>Particípio perfeito <span class=\"greek\">εὐλογημένος</span></strong>, «abençoado» (LXX; Sl 5:19; Justino, D. 121, 1 e outros), 1Cl 30:5 (Jó 11:2), 8. <span class=\"greek\">σῶμα</span> … <span class=\"greek\">εὐ</span>., «corpo abençoado», AcPlCor 2:27. Acerca de uma criança (Dt 28:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:42</a>b; <span class=\"greek\">εὐλογημένη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">γυναιξίν</span>, «bendita entre as mulheres», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:28</a>, variante textual; 42a; GJs 11:1; 12:1. Cf. <span class=\"greek\">εὐλόγησόν</span> <span class=\"greek\">με</span>, «abençoa-me», GJs 2:4 (na oração de Ana por um filho); 4:4. <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span>, «em todos os aspectos», IEph 2:1. <span class=\"greek\">ἐν</span> <span class=\"greek\">μεγέθει</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">πληρώματι</span>, «na plenitude da grandeza de Deus Pai», IEph, inscrição. <span class=\"greek\">ἐν</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">θεοῦ</span>, «pela graça de Deus», IMg, inscrição. <span class=\"greek\">εὐλογημένοι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>, «abençoados pelo Pai», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:34</a>; <span class=\"greek\">τοῖς</span> <span class=\"greek\">ηὐλογημένοις</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «aos que foram abençoados por Deus», 1Cl 30:8 (cf. Is 61:9 <span class=\"greek\">σπέρμα</span> <span class=\"greek\">ηὐλογημένον</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θεοῦ</span>).</p><p class=\"entry-text\"><strong>Bibliografia:</strong> sobre <span class=\"greek\">εὐλογέω</span> e <span class=\"greek\">εὐλογία</span>, T. Schermann, <em>Allg. Kirchenordnung</em> (1914/16), II, 640, 4; J. Hempel, «D. israel. Ansch. v. Segen u. Fluch im Lichte d. altoriental. Parallelen», ZDMG, nova série 4 (1925), 20–110; E. Maass, «Segnen, Weihen, Taufen», ARW 21 (1922), 241–81; L. Brun, <em>Segen u. Fluch im Urchristentum</em> (1932); J. Zdevsar, <em>Eulogia u. Eulogein im NT</em>, tese, Roma (1954); A. Murtonen, VetusT 9 (1959), 158–77; E. Kleszmann, <em>Monatsschr. für Past.-Theol.</em> 48 (1959), 26–39; B. Westcott, <em>Hebrews</em> (1889), 203–10; B. 1479; <em>New Docs</em> 4, 151s.; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-eulogetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλογητός, ή, όν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eulogētós⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐλογητός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span>. Ver os verbetes anterior e seguinte. Na literatura aqui abrangida, somente <strong>referente a Deus (e a Cristo)</strong>, como predominantemente na LXX; cf. En 22:14; TestSol; JosAs; ParJer; Herm. Wr. 1, 32, <span class=\"greek\">εὐλογητὸς</span> <span class=\"greek\">εἶ</span> <span class=\"greek\">πάτερ</span>, «bendito és tu, Pai». <span class=\"greek\">εὐ</span>. <span class=\"greek\">κύριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰσραήλ</span>, «bendito seja o Senhor, Deus de Israel» (3Km 1:48; 2Cr 2:11; 6:4; Sl 71:18): <strong>bendito; louvado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.68\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:68</a> (P. Vielhauer, ZTK 49 [1952], 255–72; A. Vanhoye, «Structure du ‘Benedictus’», NTS 12 [1966], 382–89; U. Mittman-Richert, <em>Magnifikat und Benediktus</em> [1996]).</p><p class=\"entry-text\"><span class=\"greek\">εὐ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰῶνας</span>, «bendito para sempre» (Sl 88:53; 40:14), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:25</a>; 9:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:31</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:3</a>; B 6:10; IEph 1:3. Sobre a formulação de louvor, ver Elbogen 4s. e P. Schorlemmer, «Die Hochkirche» (1924), 110ss., 151. <strong>Referente a Cristo:</strong> MPol 14:1.</p><p class=\"entry-text\"><span class=\"greek\">ὁ</span> <span class=\"greek\">εὐ</span>., «o Bendito», <strong>perífrase do nome de Deus</strong>, que não é pronunciado por reverência: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.61\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:61</a> (Dalman, <em>Worte</em>, 163s.). Bibliografia: E. Bishop, <em>I. Goldziher Memorial</em> I (1949), 82–88; S. Esh, <em>Der Heilige (Er Sei Gepriesen)</em> (1957); DELG, s.v. <span class=\"greek\">λέγω</span>; TW.</p></section></article>\n<article id=\"entry-eulogia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐλογία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eulogía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐλογία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver os dois verbetes precedentes. Píndaro e posteriores.</p><p class=\"entry-text\">① <strong>Ato de falar em termos favoráveis: louvor; elogio</strong> (Píndaro, Tucídides e outros; OGI 74 [séc. III a.C.] <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εὐλογία</span>, «louvor a Deus», <span class=\"greek\">Θεύδοτος</span> <span class=\"greek\">Ἰουδαῖος</span> <span class=\"greek\">σωθεὶς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πελάγους</span>, «Teódoto, judeu, salvo do mar»; Sb 317; 1117; T. Kellis 22, 11s.; Herm. Wr. 1, 30, <span class=\"greek\">εὐ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">πατρὶ</span> <span class=\"greek\">θεῷ</span>; 2Esd 19:5; Sir 50:20; Josefo, Ant. 11, 80, <span class=\"greek\">εἰς</span> <span class=\"greek\">θεόν</span>). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:12</a>s.; 7:12.</p><p class=\"entry-text\">② <strong>Por extensão do sentido «falar belamente»</strong> (Platão, Rep. 3, 400d; Luciano, Lexiph. 1), <span class=\"greek\">ἐ</span>. (abreviação que aparece nesse ponto da transcrição original para <span class=\"greek\">εὐλογία</span>) adquire sentido pejorativo (Esopo 274 e 274b H. = 155 P., 222 Ch., 160 H-H., emprega o adjetivo <span class=\"greek\">εὔλογος</span> para um argumento que soa convincente, mas é falso; cf. Luciano, Abdic. 22), especialmente acerca de <strong>palavras bem escolhidas, porém falsas: eloquência enganosa; lisonja; adulação</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16:18</a> (variante textual <span class=\"greek\">εὐγλωττίας</span>).</p><p class=\"entry-text\">③ <strong>Ato ou benefício de abençoar: bênção.</strong></p><p class=\"entry-text\">ⓐ <strong>Bênção pela qual pessoas invocam a graça de Deus sobre outras pessoas</strong> (em oposição a <span class=\"greek\">κατάρα</span>, «maldição», como Gn 27:12; Sir 3:9; Fílon, Mos. 1, 283; Josefo, Ant. 4, 302; TestBenj 6:5; JosAs 9:1): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:10</a>. Frequentemente se considera que a explicação de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:17</a> está em Gn 27:38; outros classificam essa passagem sob ⓑ <span class=\"greek\">α</span> abaixo. <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ζαχαρίου</span>, «a bênção de Zacarias», GJs 24:1.</p><p class=\"entry-text\">ⓑ <strong>Atividade de Deus ao abençoar (<span class=\"greek\">εὐ</span>.)</strong> (Wsd 15:19; Sir 11:22 e outros): 1Cl 31:1. <span class=\"greek\">ὁδοὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">εὐλογίας</span>, «os caminhos da bênção», isto é, «os caminhos que Deus abençoa», ibid.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">α</span>. <strong>Benefício concedido por Deus ou Cristo</strong> (Gn 49:25; Êx 32:29; Lv 25:21 e outros; PsSol 5:17; JosAs 24:6). <span class=\"greek\">μεταλαμβάνει</span> <span class=\"greek\">εὐλογίας</span>, «participa da bênção», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:7</a> (mas ver ④ abaixo). <span class=\"greek\">εὐ</span>. <span class=\"greek\">πνευματική</span>, «bênção espiritual», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:3</a>. <span class=\"greek\">εὐ</span>. <span class=\"greek\">Χριστοῦ</span>, «bênção de Cristo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:29</a>; <span class=\"greek\">κληρονομεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐ</span>., «herdar a bênção», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:17</a> (ver ⓐ acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:9</a>. <span class=\"greek\">εὐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀβραάμ</span>, «bênção de Abraão», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:14</a> (cf. Gn 28:4). <span class=\"greek\">ἐσχάτην</span> <span class=\"greek\">εὐ</span>., «bênção última ou mais excelente», GJs 6:2 (cf. Justino, D. 91, 1 <span class=\"greek\">εὐλογίᾳ</span>, <span class=\"greek\">ἥν</span> <span class=\"greek\">εὐλόγει</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰωσήφ</span>; ver também <span class=\"greek\">εὐλογέω</span> ③).</p><p class=\"entry-text\">ⓑ <span class=\"greek\">β</span>. <strong>Em sentido especial de benefício divino conferido na Eucaristia: bênção</strong> (<span class=\"greek\">εὐλογέω</span> ②ⓑ): <span class=\"greek\">τὸ</span> <span class=\"greek\">ποτήριον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐ</span>., «o cálice que transmite bênção», definido como «participação no sangue de Cristo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:16</a> (JosAs 8:11 <span class=\"greek\">καὶ</span> <span class=\"greek\">πιέτω</span> <span class=\"greek\">ποτήριον</span> <span class=\"greek\">εὐλογίας</span> <span class=\"greek\">σου</span>; aí a expressão é um termo técnico para o cálice de vinho bebido ao fim de uma refeição israelita; H. Gressmann, <em>Sellin Festschrift</em> [1927], 55ss.; R. Otto, <em>The Kingdom of God and the Son of Man</em>, trad. F. Filson e B. Lee-Woolf [1957], 265ss.).</p><p class=\"entry-text\">ⓒ <strong>Benefício oferecido por seres humanos</strong> (Gn 33:11; 1Km 25:27; 4Km 5:15. Cirilo de Citópolis emprega <span class=\"greek\">εὐλογία</span> no sentido de «dádiva; presente [humano]» sem influência bíblica: 68, 17, 28; 217, 16; 238, 12; também <span class=\"greek\">εὐλογέω</span> como «conceder»: 137, 9): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:5</a>a; alguns intérpretes preferem aí a acepção ④.</p><p class=\"entry-text\">④ <strong>Como o conceito de bênção traz a ideia de generosidade, <span class=\"greek\">εὐλογία</span> também significa presente generoso; dádiva; liberalidade</strong> (em oposição a <span class=\"greek\">πλεονεξία</span>, «avareza»): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:5</a>b; talvez também 9:5a (ver ③ⓒ acima). <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">εὐλογίαις</span>, «generosamente», em oposição a <span class=\"greek\">φειδομένως</span>, «parcimoniosamente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:6</a>a,b (Fílon, Leg. All. 3, 210: <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">εὐλογίαις</span>, «para que se faça sentir uma influência abençoadora»).</p><p class=\"entry-text\">Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:7</a> deva igualmente ser colocado nesta acepção (ver ③ⓑ<span class=\"greek\">α</span>): <span class=\"greek\">γῆ</span> … <span class=\"greek\">μεταλαμβάνει</span> <span class=\"greek\">εὐλογίας</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «a terra recebe de Deus benefícios abundantes».</p><p class=\"entry-text\"><strong>Bibliografia:</strong> RAC VI 900–928; J. Mateos, «Análisis de un campo lexemático — <span class=\"greek\">Εὐλογία</span> en el NT», <em>Filología Neotestamentaria</em> 1 (1988), 5–25; cf. Betz, <em>2 Cor</em>, 96–99, 103; Renehan (1985), 73s.; M-M; TW.</p></section></article>\n<article id=\"entry-eulogos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔλογος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eúlogos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὔλογος</span>, <span class=\"greek\">ον</span>. Ver os três verbetes precedentes. Ésquilo e outros; OGI 504, 9; 669, 10; UPZ 162 V, 2 [117 a.C.]; Fílon; Josefo, C. Ap. 1, 259; Justino, D. 56, 10; Taciano 9:1; Atenágoras, R. 49, 23. <strong>Aquilo que possui bom sentido: razoável; correto; sensato</strong>, IMg 7:1. <span class=\"greek\">εὔλογόν</span> <span class=\"greek\">ἐστιν</span>, «é razoável», seguido de infinitivo (Platão, Crat. 396b; cf. Fílon, Deus Imm. 127), ISm 9:1.</p></section></article>\n"};
